def search(query, type=None, page=None, hitsPerPage=None, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0103000" if __import__("os").path.isdir("./environment_mix/0103000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    start = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    # Defaults
    if type is None:
        type = "all"
    if page is None:
        page = 0
    if hitsPerPage is None:
        hitsPerPage = 20

    # Prepare request log row early (immutable meaning)
    def _new_id(prefix="hnreq"):
        import secrets
        return f"{prefix}_{secrets.token_hex(12)}"

    reqs = _load("hn_requests.json")
    req_id = _new_id()
    req_row = {
        "id": req_id,
        "tool_name": "search",
        "status": "received",
        "query": query if isinstance(query, str) else None,
        "search_type": type if isinstance(type, str) else None,
        "page": int(page) if isinstance(page, (int, float)) and int(page) == page else (page if isinstance(page, int) else None),
        "hits_per_page": int(hitsPerPage) if isinstance(hitsPerPage, (int, float)) and int(hitsPerPage) == hitsPerPage else (hitsPerPage if isinstance(hitsPerPage, int) else None),
        "story_hn_item_id": None,
        "comment_hn_item_id": None,
        "stories_type": None,
        "limit": None,
        "user_hn_username": None,
        "response_cached_object_ids": None,
        "upstream_provider": None,
        "upstream_latency_ms": None,
        "error_message": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    reqs.append(req_row)
    _save("hn_requests.json", reqs)

    # Quota / rate-limit enforcement (simple, observable via hn_requests)
    # - Per-minute cap for search: 120
    # - Per-day cap for search: 5000
    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    minute_ago = now - datetime.timedelta(seconds=60)
    day_ago = now - datetime.timedelta(days=1)
    per_min = 0
    per_day = 0
    for r in reqs:
        if r.get("tool_name") != "search":
            continue
        ts = _parse_dt(r.get("created_at"))
        if not ts:
            continue
        if ts >= minute_ago:
            per_min += 1
        if ts >= day_ago:
            per_day += 1
    # include current request already appended
    if per_min > 120 or per_day > 5000:
        # Update request status
        for r in reqs[::-1]:
            if r.get("id") == req_id:
                r["status"] = "failed"
                r["error_message"] = "Quota exceeded for search"
                r["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                break
        _save("hn_requests.json", reqs)
        return _err("QUOTA_EXCEEDED", "Quota exceeded")

    # Validation
    if not isinstance(query, str) or not query.strip():
        for r in reqs[::-1]:
            if r.get("id") == req_id:
                r["status"] = "failed"
                r["error_message"] = "query must be a non-empty string"
                r["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                break
        _save("hn_requests.json", reqs)
        return _err("VALIDATION_ERROR", "query must be a non-empty string")

    if type not in ("all", "story", "comment"):
        for r in reqs[::-1]:
            if r.get("id") == req_id:
                r["status"] = "failed"
                r["error_message"] = "type must be one of all|story|comment"
                r["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                break
        _save("hn_requests.json", reqs)
        return _err("VALIDATION_ERROR", "type must be one of all|story|comment")

    if not isinstance(page, (int, float)) or int(page) != page or int(page) < 0:
        for r in reqs[::-1]:
            if r.get("id") == req_id:
                r["status"] = "failed"
                r["error_message"] = "page must be a non-negative integer"
                r["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                break
        _save("hn_requests.json", reqs)
        return _err("VALIDATION_ERROR", "page must be a non-negative integer")
    page = int(page)

    if not isinstance(hitsPerPage, (int, float)) or int(hitsPerPage) != hitsPerPage or int(hitsPerPage) < 1 or int(hitsPerPage) > 100:
        for r in reqs[::-1]:
            if r.get("id") == req_id:
                r["status"] = "failed"
                r["error_message"] = "hitsPerPage must be an integer between 1 and 100"
                r["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                break
        _save("hn_requests.json", reqs)
        return _err("VALIDATION_ERROR", "hitsPerPage must be an integer between 1 and 100")
    hitsPerPage = int(hitsPerPage)

    # Search cached items (only active by default)
    items = _load("hn_items.json")
    q = query.strip().lower()
    # simple tokenization
    tokens = [t for t in re.split(r"\s+", q) if t]
    def _hay(it):
        parts = []
        for k in ("title", "text", "url", "hn_author"):
            v = it.get(k)
            if isinstance(v, str) and v:
                parts.append(v.lower())
        return " ".join(parts)

    candidates = []
    for it in items:
        if it.get("status") != "active":
            continue
        it_type = it.get("item_type")
        if type == "story" and it_type != "story":
            continue
        if type == "comment" and it_type != "comment":
            continue
        hay = _hay(it)
        if not hay:
            continue
        ok = True
        for t in tokens:
            if t not in hay:
                ok = False
                break
        if not ok:
            continue
        # light scoring: prefer title match and higher score
        score = 0
        title = (it.get("title") or "").lower()
        text = (it.get("text") or "").lower()
        for t in tokens:
            if t in title:
                score += 3
            if t in text:
                score += 1
        hn_score = it.get("score")
        if isinstance(hn_score, int) and hn_score >= 0:
            score += min(50, hn_score // 10)
        candidates.append((score, it))

    # Sort
    def _parse_item_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    candidates.sort(key=lambda si: (si[0], _parse_item_dt(si[1].get("hn_created_at") or si[1].get("fetched_at") or si[1].get("updated_at")) or datetime.datetime(1970, 1, 1)), reverse=True)
    total = len(candidates)
    start_idx = page * hitsPerPage
    end_idx = start_idx + hitsPerPage
    page_rows = [it for _, it in candidates[start_idx:end_idx]]

    resp_ids = [r.get("id") for r in page_rows if isinstance(r.get("id"), str)]
    has_more = end_idx < total
    latency_ms = int((time.time() - start) * 1000)

    # Update request row: served_from_cache
    reqs = _load("hn_requests.json")
    for r in reqs[::-1]:
        if r.get("id") == req_id:
            r["status"] = "served_from_cache"
            r["response_cached_object_ids"] = resp_ids
            r["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            break
    _save("hn_requests.json", reqs)

    return {
        "hits": page_rows,
        "page": page,
        "hitsPerPage": hitsPerPage,
        "nbHits": total,
        "nbPages": (total + hitsPerPage - 1) // hitsPerPage if hitsPerPage else 0,
        "has_more": has_more,
        "request": {"id": req_id, "status": "served_from_cache", "latency_ms": latency_ms},
    }

def getStory(id, **_extra):
    import json, os, datetime, time, secrets
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0103000" if __import__("os").path.isdir("./environment_mix/0103000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0)
    def _now_iso():
        return _now().isoformat() + "Z"

    def _parse_num_as_int(v):
        if isinstance(v, bool) or v is None:
            return None
        if isinstance(v, int):
            return v
        if isinstance(v, float):
            if not (v == v and abs(v) != float("inf")):
                return None
            if int(v) != v:
                return None
            return int(v)
        return None

    def _parse_iso(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            ss = s[:-1] if s.endswith("Z") else s
            return datetime.datetime.fromisoformat(ss)
        except Exception:
            return None

    def _gen_id(prefix):
        return f"{prefix}_{secrets.token_hex(12)}"

    def _enforce_limits(reqs):
        now_dt = _now()
        minute_ago = now_dt - datetime.timedelta(seconds=60)
        day_ago = now_dt - datetime.timedelta(days=1)
        per_min = 0
        per_day = 0
        for r in reqs:
            ts = _parse_iso(r.get("created_at"))
            if not ts:
                continue
            if ts >= minute_ago:
                per_min += 1
            if ts >= day_ago:
                per_day += 1
        if per_min >= 240:
            return _err("RATE_LIMIT", "Rate limit exceeded (max 240 requests/min across this datastore).", limit_per_minute=240)
        if per_day >= 5000:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded (max 5000 requests/day across this datastore).", limit_per_day=5000)
        return None

    hn_id = _parse_num_as_int(id)
    if hn_id is None or hn_id <= 0:
        return _err("VALIDATION_ERROR", "Parameter 'id' is required and must be a positive integer-valued number.", id=id)

    t0 = time.time()
    reqs = _load("hn_requests.json")
    if not isinstance(reqs, list):
        reqs = []
    limit_err = _enforce_limits(reqs)
    if limit_err:
        return limit_err

    # log request as received
    now_iso = _now_iso()
    req_row_id = _gen_id("hn_req")
    req_row = {
        "id": req_row_id,
        "tool_name": "getStory",
        "status": "received",
        "query": None,
        "search_type": None,
        "page": None,
        "hits_per_page": None,
        "story_hn_item_id": hn_id,
        "comment_hn_item_id": None,
        "stories_type": None,
        "limit": None,
        "user_hn_username": None,
        "response_cached_object_ids": None,
        "upstream_provider": None,
        "upstream_latency_ms": None,
        "error_message": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    reqs.append(req_row)
    _save("hn_requests.json", reqs)

    items = _load("hn_items.json")
    if not isinstance(items, list):
        items = []

    story = None
    for it in items:
        if it.get("hn_item_id") == hn_id and it.get("item_type") == "story":
            story = it
            break

    # served from cache if found, otherwise return NOT_FOUND (no upstream available offline)
    end_iso = _now_iso()
    latency_ms = int(max(0, (time.time() - t0) * 1000))

    # update request row (mutable fields only)
    for r in reqs:
        if r.get("id") == req_row_id:
            if story is not None:
                r["status"] = "served_from_cache"
                r["response_cached_object_ids"] = [story.get("id")] if story.get("id") else None
            else:
                r["status"] = "failed"
                r["error_message"] = "Story does not exist or is not a story."
            r["updated_at"] = end_iso
            break
    _save("hn_requests.json", reqs)

    if story is None:
        return _err("NOT_FOUND", "Story does not exist or is not a story.", hn_item_id=hn_id)

    return {
        "story": story,
        "request": {"id": req_row_id, "status": "served_from_cache", "latency_ms": latency_ms},
    }

def getStoryWithComments(id, **_extra):
    import json, os, datetime, time, secrets
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0103000" if __import__("os").path.isdir("./environment_mix/0103000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0)
    def _now_iso():
        return _now().isoformat() + "Z"

    def _parse_num_as_int(v):
        if isinstance(v, bool) or v is None:
            return None
        if isinstance(v, int):
            return v
        if isinstance(v, float):
            if not (v == v and abs(v) != float("inf")):
                return None
            if int(v) != v:
                return None
            return int(v)
        return None

    def _parse_iso(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            ss = s[:-1] if s.endswith("Z") else s
            return datetime.datetime.fromisoformat(ss)
        except Exception:
            return None

    def _gen_id(prefix):
        return f"{prefix}_{secrets.token_hex(12)}"

    def _enforce_limits(reqs):
        now_dt = _now()
        minute_ago = now_dt - datetime.timedelta(seconds=60)
        day_ago = now_dt - datetime.timedelta(days=1)
        per_min = 0
        per_day = 0
        for r in reqs:
            ts = _parse_iso(r.get("created_at"))
            if not ts:
                continue
            if ts >= minute_ago:
                per_min += 1
            if ts >= day_ago:
                per_day += 1
        if per_min >= 240:
            return _err("RATE_LIMIT", "Rate limit exceeded (max 240 requests/min across this datastore).", limit_per_minute=240)
        if per_day >= 5000:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded (max 5000 requests/day across this datastore).", limit_per_day=5000)
        return None

    hn_id = _parse_num_as_int(id)
    if hn_id is None or hn_id <= 0:
        return _err("VALIDATION_ERROR", "Parameter 'id' is required and must be a positive integer-valued number.", id=id)

    t0 = time.time()
    reqs = _load("hn_requests.json")
    if not isinstance(reqs, list):
        reqs = []
    limit_err = _enforce_limits(reqs)
    if limit_err:
        return limit_err

    now_iso = _now_iso()
    req_row_id = _gen_id("hn_req")
    req_row = {
        "id": req_row_id,
        "tool_name": "getStoryWithComments",
        "status": "received",
        "query": None,
        "search_type": None,
        "page": None,
        "hits_per_page": None,
        "story_hn_item_id": hn_id,
        "comment_hn_item_id": None,
        "stories_type": None,
        "limit": None,
        "user_hn_username": None,
        "response_cached_object_ids": None,
        "upstream_provider": None,
        "upstream_latency_ms": None,
        "error_message": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    reqs.append(req_row)
    _save("hn_requests.json", reqs)

    items = _load("hn_items.json")
    if not isinstance(items, list):
        items = []
    edges = _load("hn_item_edges.json")
    if not isinstance(edges, list):
        edges = []

    # index items by internal id and also find story
    by_internal_id = {}
    story = None
    for it in items:
        iid = it.get("id")
        if iid:
            by_internal_id[iid] = it
        if it.get("hn_item_id") == hn_id and it.get("item_type") == "story":
            story = it

    def _is_visible_item(it):
        # default exclusion for deleted/dead/tombstoned
        return isinstance(it, dict) and it.get("status") == "active"

    if story is None:
        # update req then error
        for r in reqs:
            if r.get("id") == req_row_id:
                r["status"] = "failed"
                r["error_message"] = "Story does not exist or is not a story."
                r["updated_at"] = _now_iso()
                break
        _save("hn_requests.json", reqs)
        return _err("NOT_FOUND", "Story does not exist or is not a story.", hn_item_id=hn_id)

    story_internal_id = story.get("id")
    # gather edges for this story's root id
    story_edges = [e for e in edges if e.get("root_story_item_id") == story_internal_id]

    # adjacency: parent_internal_id -> list of (sort_order, child_internal_id)
    children_map = {}
    for e in story_edges:
        p = e.get("parent_item_id")
        c = e.get("child_item_id")
        if not p or not c:
            continue
        # FK integrity: only keep if both exist
        if p not in by_internal_id or c not in by_internal_id:
            continue
        so = e.get("sort_order")
        so_val = so if isinstance(so, int) and so >= 0 else None
        children_map.setdefault(p, []).append((so_val, c))

    # stable sort: sort_order, else hn_created_at, else created_at, else 0
    def _sort_key(pair):
        so_val, cid = pair
        it = by_internal_id.get(cid, {})
        if so_val is not None:
            return (0, so_val, 0, "")
        # fallback to times
        t = it.get("hn_created_at") or it.get("created_at") or ""
        return (1, 10**9, 0, str(t))

    for p, lst in list(children_map.items()):
        lst.sort(key=_sort_key)
        children_map[p] = [cid for _, cid in lst]

    visited = set()

    def _build_node(internal_id):
        if internal_id in visited:
            return None
        visited.add(internal_id)
        it = by_internal_id.get(internal_id)
        if not _is_visible_item(it):
            return None
        node = {"item": it, "replies": []}
        for child_id in children_map.get(internal_id, []):
            child_node = _build_node(child_id)
            if child_node is not None:
                node["replies"].append(child_node)
        return node

    # top-level comments are children of the story
    thread = []
    for cid in children_map.get(story_internal_id, []):
        n = _build_node(cid)
        if n is not None:
            thread.append(n)

    # update request row
    response_ids = [story.get("id")] + [n["item"].get("id") for n in thread if n.get("item", {}).get("id")]
    for r in reqs:
        if r.get("id") == req_row_id:
            r["status"] = "served_from_cache"
            r["response_cached_object_ids"] = [x for x in response_ids if x]
            r["updated_at"] = _now_iso()
            break
    _save("hn_requests.json", reqs)

    latency_ms = int(max(0, (time.time() - t0) * 1000))
    return {
        "story": story,
        "comments": thread,
        "request": {"id": req_row_id, "status": "served_from_cache", "latency_ms": latency_ms},
    }

def getStories(type, limit=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0103000" if __import__("os").path.isdir("./environment_mix/0103000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    start = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    if limit is None:
        limit = 30

    def _new_id(prefix="hnreq"):
        import secrets
        return f"{prefix}_{secrets.token_hex(12)}"

    # Log received
    reqs = _load("hn_requests.json")
    req_id = _new_id()
    limit_int = int(limit) if isinstance(limit, (int, float)) and int(limit) == limit else None
    reqs.append({
        "id": req_id,
        "tool_name": "getStories",
        "status": "received",
        "query": None,
        "search_type": None,
        "page": None,
        "hits_per_page": None,
        "story_hn_item_id": None,
        "comment_hn_item_id": None,
        "stories_type": type if isinstance(type, str) else None,
        "limit": limit_int,
        "user_hn_username": None,
        "response_cached_object_ids": None,
        "upstream_provider": None,
        "upstream_latency_ms": None,
        "error_message": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    })
    _save("hn_requests.json", reqs)

    # Quota (list fetch tends to be stricter)
    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    reqs = _load("hn_requests.json")
    minute_ago = now - datetime.timedelta(seconds=60)
    hour_ago = now - datetime.timedelta(hours=1)
    per_min = per_hour = 0
    for r in reqs:
        if r.get("tool_name") != "getStories":
            continue
        ts = _parse_dt(r.get("created_at"))
        if not ts:
            continue
        if ts >= minute_ago: per_min += 1
        if ts >= hour_ago: per_hour += 1
    if per_min > 60 or per_hour > 1000:
        for r in reqs[::-1]:
            if r.get("id") == req_id:
                r["status"] = "failed"
                r["error_message"] = "Rate limit exceeded for getStories"
                r["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                break
        _save("hn_requests.json", reqs)
        return _err("RATE_LIMIT", "Rate limit exceeded")

    # Validate
    if type not in ("top", "new", "best", "ask", "show", "job"):
        reqs = _load("hn_requests.json")
        for r in reqs[::-1]:
            if r.get("id") == req_id:
                r["status"] = "failed"
                r["error_message"] = "type must be one of top|new|best|ask|show|job"
                r["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                break
        _save("hn_requests.json", reqs)
        return _err("VALIDATION_ERROR", "type must be one of top|new|best|ask|show|job")

    if limit_int is None or limit_int < 1 or limit_int > 500:
        reqs = _load("hn_requests.json")
        for r in reqs[::-1]:
            if r.get("id") == req_id:
                r["status"] = "failed"
                r["error_message"] = "limit must be an integer between 1 and 500"
                r["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                break
        _save("hn_requests.json", reqs)
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 500")
    limit = limit_int

    lists = _load("hn_story_lists.json")
    list_row = None
    for lr in lists:
        if lr.get("list_type") == type:
            list_row = lr
            break

    # Determine stale/expired
    def _is_expired(lr):
        exp = _parse_dt(lr.get("expires_at"))
        if exp and now >= exp:
            return True
        # If no expires_at, consider stale if fetched_at older than 10 minutes
        ft = _parse_dt(lr.get("fetched_at"))
        if not ft:
            return True
        return (now - ft) > datetime.timedelta(minutes=10)

    # If absent or stale/expired, real service may refresh; offline we cannot fetch, but we can transition stale->refreshing->failed
    if list_row is None:
        # No list cached => NOT_FOUND equivalent? Real API would fetch; we can't. Return empty but record failure? Spec doesn't say.
        # We'll fail with NOT_FOUND to avoid inventing data.
        reqs = _load("hn_requests.json")
        for r in reqs[::-1]:
            if r.get("id") == req_id:
                r["status"] = "failed"
                r["error_message"] = "Story list not found in cache and upstream fetch unavailable"
                r["upstream_provider"] = "hn_firebase"
                r["upstream_latency_ms"] = 0
                r["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                break
        _save("hn_requests.json", reqs)
        return _err("NOT_FOUND", "Story list not found")

    # Respect lifecycle transitions for hn_story_lists if expired/stale
    if list_row.get("status") in ("fresh", "stale") and _is_expired(list_row):
        # Transition fresh->stale if fresh
        if list_row.get("status") == "fresh":
            list_row["status"] = "stale"
            list_row["updated_at"] = now_iso
        # Transition stale->refreshing
        if list_row.get("status") == "stale":
            list_row["status"] = "refreshing"
            list_row["updated_at"] = now_iso
        # "Fetch" attempt fails offline => refreshing->failed (legal)
        if list_row.get("status") == "refreshing":
            list_row["status"] = "failed"
            list_row["error_message"] = "Upstream fetch unavailable"
            list_row["updated_at"] = now_iso
        _save("hn_story_lists.json", lists)

    hn_story_ids = list_row.get("hn_story_ids") if isinstance(list_row.get("hn_story_ids"), list) else []
    hn_story_ids = [x for x in hn_story_ids if isinstance(x, int) and x > 0]
    hn_story_ids = hn_story_ids[:limit]

    items = _load("hn_items.json")
    by_hn = {}
    for it in items:
        hnid = it.get("hn_item_id")
        if isinstance(hnid, int):
            by_hn[hnid] = it

    # Return only stories that exist and are active
    stories = []
    resp_ids = []
    for hnid in hn_story_ids:
        it = by_hn.get(hnid)
        if not it:
            continue
        if it.get("item_type") != "story":
            continue
        if it.get("status") != "active":
            continue
        stories.append(it)
        if isinstance(it.get("id"), str):
            resp_ids.append(it["id"])

    latency_ms = int((time.time() - start) * 1000)
    reqs = _load("hn_requests.json")
    for r in reqs[::-1]:
        if r.get("id") == req_id:
            r["status"] = "served_from_cache"
            r["response_cached_object_ids"] = resp_ids
            r["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            break
    _save("hn_requests.json", reqs)

    return {
        "type": type,
        "limit": limit,
        "list": list_row,
        "stories": stories,
        "has_more": len(hn_story_ids) > len(stories) or len(hn_story_ids) == limit,
        "request": {"id": req_id, "status": "served_from_cache", "latency_ms": latency_ms},
    }

