        visited.add(internal_id)
        it = by_internal_id.get(internal_id)
        if not _is_visible_item(it):
            return None
        node = {"item": it, "replies": []}
        for cid in children_map.get(internal_id, []):
            cn = _build(cid)
            if cn is not None:
                node["replies"].append(cn)
        return node

    tree = {"story": story, "comments": []}
    response_ids = [story_internal_id] if story_internal_id else []

    for cid in children_map.get(story_internal_id, []):
        n = _build(cid)
        if n is not None:
            tree["comments"].append(n)
            if n.get("item", {}).get("id"):
                response_ids.append(n["item"]["id"])

