        "status": "received",
        "query": None,
        "search_type": None,
        "page": None,
        "hits_per_page": None,
        "story_hn_item_id": None,
        "comment_hn_item_id": None,
        "stories_type": None,
        "limit": None,
        "user_hn_username": None,
        "response_cached_object_ids": None,
        "upstream_provider": None,
        "upstream_latency_ms": None,
        "error_message": None,
        "created_at": created_at,
        "updated_at": created_at,
    }

    # Validate id
    try:
        if id is None:
            req_row["status"] = "failed"
            req_row["error_message"] = "id is required"
            req_row["updated_at"] = _now_iso()
            requests.append(req_row); _save("hn_requests.json", requests)
            return _err("VALIDATION_ERROR", "id is required")
        if not isinstance(id, str):
            req_row["status"] = "failed"
            req_row["error_message"] = "id must be a string"
            req_row["updated_at"] = _now_iso()
            requests.append(req_row); _save("hn_requests.json", requests)
            return _err("VALIDATION_ERROR", "id must be a string")
        username = id.strip()
        if not username:
            req_row["status"] = "failed"
            req_row["error_message"] = "id must not be empty"
            req_row["updated_at"] = _now_iso()
            requests.append(req_row); _save("hn_requests.json", requests)
            return _err("VALIDATION_ERROR", "id must not be empty")
    except Exception as e:
        req_row["status"] = "failed"
        req_row["error_message"] = f"invalid id: {e}"
        req_row["updated_at"] = _now_iso()
        requests.append(req_row); _save("hn_requests.json", requests)
        return _err("VALIDATION_ERROR", "invalid id")

    req_row["user_hn_username"] = username

    # Ambient auth
    try:
        if not os.path.isdir(_DB):
            req_row["status"] = "failed"
            req_row["error_message"] = "integration datastore unavailable"
            req_row["updated_at"] = _now_iso()
            requests.append(req_row); _save("hn_requests.json", requests)
            return _err("UNAUTHORIZED", "Integration not permitted for caller")
    except Exception as e:
        req_row["status"] = "failed"
        req_row["error_message"] = f"auth check failed: {e}"
        req_row["updated_at"] = _now_iso()
        requests.append(req_row); _save("hn_requests.json", requests)
        return _err("UNAUTHORIZED", "Integration not permitted for caller")

    users = _load("hn_users.json")

    user = None
    for u in users:
        if u.get("hn_username") == username:
            user = u
            break

    if not user:
        req_row["status"] = "failed"
        req_row["error_message"] = "user not found"
        req_row["updated_at"] = _now_iso()
        requests.append(req_row); _save("hn_requests.json", requests)
        return _err("NOT_FOUND", "User not found")

    # If user deleted/tombstoned, treat as not found to match "user does not exist"
    if user.get("status") in ("deleted", "tombstoned"):
        req_row["status"] = "failed"
        req_row["error_message"] = f"user status is {user.get('status')}"
        req_row["updated_at"] = _now_iso()
        requests.append(req_row); _save("hn_requests.json", requests)
        return _err("NOT_FOUND", "User not found")

    # No upstream available offline; serve cached, but annotate staleness.
    served_status = "served_from_cache"

    # Log request
    returned_ids = [user.get("id")] if isinstance(user.get("id"), str) else None
    req_row["status"] = served_status
    req_row["response_cached_object_ids"] = returned_ids
    req_row["updated_at"] = _now_iso()
    try:
        latency_ms = int((time.time() - start_t) * 1000)
    except Exception:
        latency_ms = None
    requests.append(req_row)
    _save("hn_requests.json", requests)

    return {
        "user": dict(user),
        "meta": {
            "served_from_cache": True,
            "stale": _is_stale(user.get("fetched_at")),
            "request_id": req_id,
            "latency_ms": latency_ms,
        },
    }

def getUserSubmissions(id, **_extra):
    import json, os, datetime

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0103000" if __import__("os").path.isdir("./environment_mix/0103000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, (int, float)):
            return datetime.datetime.utcfromtimestamp(v)
        if isinstance(v, str):
            s = v.strip()
            if s.endswith("Z"):
                s = s[:-1]
            try:
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None
        return None

    def _gen_id(prefix):
        import secrets
        return f"{prefix}_{secrets.token_hex(12)}"

    def _log_request(req_row):
        reqs = _load("hn_requests.json")
        reqs.append(req_row)
        _save("hn_requests.json", reqs)

    # Validate input
    if id is None or not isinstance(id, str) or len(id.strip()) == 0:
        return _err("VALIDATION_ERROR", "Parameter 'id' is required and must be a non-empty string.")
    hn_username = id.strip()

    # Authenticate (ambient): permitted if datastore exists/available. If no workable store, UNAUTHORIZED.
    # Here, as long as collections can be read/written we allow.
    try:
        os.makedirs(_DB, exist_ok=True)
    except Exception:
        return _err("UNAUTHORIZED", "Integration is not permitted for the caller.")

    # Record request as received (immutable fields set now)
    request_id = _gen_id("hnreq")
    created_at = _now_iso()
    req_row = {
        "id": request_id,
        "tool_name": "getUserSubmissions",
        "status": "received",
        "query": None,
        "search_type": None,
        "page": None,
        "hits_per_page": None,
        "story_hn_item_id": None,
        "comment_hn_item_id": None,
        "stories_type": None,
        "limit": None,
        "user_hn_username": hn_username,
        "response_cached_object_ids": None,
        "upstream_provider": None,
        "upstream_latency_ms": None,
        "error_message": None,
        "created_at": created_at,
        "updated_at": created_at,
    }
    _log_request(req_row)

    # Quota enforcement (simple observable dynamic): cap requests per user per day and max returned submissions.
    # - 500 getUserSubmissions calls/day/user
    # - max 500 submissions returned
    reqs_all = _load("hn_requests.json")
    now_dt = _parse_dt(_now_iso())
    day_ago = now_dt - datetime.timedelta(days=1)
    calls_24h = 0
    for r in reqs_all:
        if r.get("tool_name") == "getUserSubmissions" and r.get("user_hn_username") == hn_username:
            t = _parse_dt(r.get("created_at"))
            if t and t >= day_ago:
                calls_24h += 1
    if calls_24h > 500:
        # update status -> failed
        for r in reqs_all:
            if r.get("id") == request_id:
                r["status"] = "failed"
                r["error_message"] = "Daily quota exceeded for getUserSubmissions."
                r["updated_at"] = _now_iso()
                break
        _save("hn_requests.json", reqs_all)
        return _err("QUOTA_EXCEEDED", "Daily quota exceeded for getUserSubmissions.", requestId=request_id, limit=500, window="24h")

    users = _load("hn_users.json")
    user_row = None
    for u in users:
        if u.get("hn_username") == hn_username:
            user_row = u
            break

    if not user_row:
        # update request -> failed
        for r in reqs_all:
            if r.get("id") == request_id:
                r["status"] = "failed"
                r["error_message"] = "User not found."
                r["updated_at"] = _now_iso()
                break
        _save("hn_requests.json", reqs_all)
        return _err("NOT_FOUND", "User does not exist.", requestId=request_id)

    # Determine staleness (treat fetched_at older than 24h as stale). We do not actually fetch upstream offline;
    # reflect cache semantics by serving from cache and leaving data unchanged.
    fetched_at_dt = _parse_dt(user_row.get("fetched_at"))
    stale = True
    if fetched_at_dt:
        stale = (now_dt - fetched_at_dt) > datetime.timedelta(hours=24)

    submitted = user_row.get("submitted_hn_item_ids")
    if submitted is None:
        submitted = []
    if not isinstance(submitted, list):
        submitted = []

    # Enforce list-fetch limit
    if len(submitted) > 500:
        submitted = submitted[:500]

    # Lazily hydrate: return cached items that exist; do not fabricate missing items.
    items = _load("hn_items.json")
    by_hn = {}
    for it in items:
        hnid = it.get("hn_item_id")
        if isinstance(hnid, int):
            by_hn[hnid] = it

    returned_items = []
    returned_ids = []
    missing_hn_ids = []
    for hnid in submitted:
        if isinstance(hnid, int) and hnid > 0:
            it = by_hn.get(hnid)
            if it:
                returned_items.append(it)
                returned_ids.append(it.get("id"))
            else:
                missing_hn_ids.append(hnid)

    # Update request status
    reqs_all = _load("hn_requests.json")
    for r in reqs_all:
        if r.get("id") == request_id:
            r["status"] = "served_from_cache"
            r["response_cached_object_ids"] = [user_row.get("id")] + [x for x in returned_ids if x]
            if stale:
                # Not fetched upstream in this offline integration, still served from cache.
                pass
            r["updated_at"] = _now_iso()
            break
    _save("hn_requests.json", reqs_all)

    return {
        "requestId": request_id,
        "user": user_row,
        "submissions": returned_items,
        "missingHnItemIds": missing_hn_ids,
        "meta": {
            "totalSubmittedIds": len(user_row.get("submitted_hn_item_ids") or []),
            "returned": len(returned_items),
            "capped": (len(user_row.get("submitted_hn_item_ids") or []) > 500),
            "staleUser": bool(stale),
        },
    }

def getRequest(id, **_extra):
    import json, os, datetime, time, secrets
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0103000" if __import__("os").path.isdir("./environment_mix/0103000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0)
    def _now_iso():
        return _now().isoformat() + "Z"

    def _parse_iso(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            ss = s[:-1] if s.endswith("Z") else s
            return datetime.datetime.fromisoformat(ss)
        except Exception:
            return None

    def _gen_id(prefix):
        return f"{prefix}_{secrets.token_hex(12)}"

    def _enforce_limits(reqs):
        now_dt = _now()
        minute_ago = now_dt - datetime.timedelta(seconds=60)
        day_ago = now_dt - datetime.timedelta(days=1)
        per_min = 0
        per_day = 0
        for r in reqs:
            ts = _parse_iso(r.get("created_at"))
            if not ts:
                continue
            if ts >= minute_ago:
                per_min += 1
            if ts >= day_ago:
                per_day += 1
        if per_min >= 240:
            return _err("RATE_LIMIT", "Rate limit exceeded (max 240 requests/min across this datastore).", limit_per_minute=240)
        if per_day >= 5000:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded (max 5000 requests/day across this datastore).", limit_per_day=5000)
        return None

    if id is None or not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "Parameter 'id' is required and must be a non-empty string.", id=id)
    rid = id.strip()

    t0 = time.time()
    reqs = _load("hn_requests.json")
    if not isinstance(reqs, list):
        reqs = []
    limit_err = _enforce_limits(reqs)
    if limit_err:
        return limit_err

    # log this call (this is a request too)
    now_iso = _now_iso()
    call_id = _gen_id("hn_req")
    call_row = {
        "id": call_id,
        "tool_name": "getRequest",
        "status": "received",
        "query": None,
        "search_type": None,
        "page": None,
        "hits_per_page": None,
        "story_hn_item_id": None,
        "comment_hn_item_id": None,
        "stories_type": None,
        "limit": None,
        "user_hn_username": None,
        "response_cached_object_ids": None,
        "upstream_provider": None,
        "upstream_latency_ms": None,
        "error_message": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    reqs.append(call_row)
    _save("hn_requests.json", reqs)

    found = None
    for r in reqs:
        if r.get("id") == rid:
            found = r
            break

    for r in reqs:
        if r.get("id") == call_id:
            if found is None:
                r["status"] = "failed"
                r["error_message"] = "Request does not exist."
            else:
                r["status"] = "served_from_cache"
                r["response_cached_object_ids"] = [rid]
            r["updated_at"] = _now_iso()
            break
    _save("hn_requests.json", reqs)

    if found is None:
        return _err("NOT_FOUND", "Request does not exist.", id=rid)

    latency_ms = int(max(0, (time.time() - t0) * 1000))
    return {"request": found, "meta": {"lookup_id": rid, "call_id": call_id, "latency_ms": latency_ms}}

def listRequests(toolName=None, status=None, query=None, searchType=None, userId=None, storiesType=None, page=None, hitsPerPage=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0103000" if __import__("os").path.isdir("./environment_mix/0103000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        import secrets
        return f"{prefix}_{secrets.token_hex(12)}"

    def _log_request(req_row):
        reqs = _load("hn_requests.json")
        reqs.append(req_row)
        _save("hn_requests.json", reqs)

    def _parse_cursor(c):
        if c is None:
            return None
        if not isinstance(c, str) or not c:
            return None
        try:
            raw = base64.urlsafe_b64decode(c.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if isinstance(obj, dict) and "offset" in obj and isinstance(obj["offset"], int) and obj["offset"] >= 0:
                return obj["offset"]
        except Exception:
            return None
        return None

    def _make_cursor(offset):
        payload = json.dumps({"offset": offset}, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(payload).decode("utf-8").rstrip("=")

    # Validate enums/types
    allowed_tool = {"search", "getStories", "getStory", "getStoryWithComments", "getComment", "getComments", "getCommentTree", "getUser", "getUserSubmissions"}
    allowed_status = {"received", "served_from_cache", "fetched_upstream", "failed"}
    allowed_search_type = {"all", "story", "comment"}
    allowed_stories_type = {"top", "new", "best", "ask", "show", "job"}

    if toolName is not None and (not isinstance(toolName, str) or toolName not in allowed_tool):
        return _err("VALIDATION_ERROR", "Invalid 'toolName'.")
    if status is not None and (not isinstance(status, str) or status not in allowed_status):
        return _err("VALIDATION_ERROR", "Invalid 'status'.")
    if query is not None and not isinstance(query, str):
        return _err("VALIDATION_ERROR", "Invalid 'query'.")
    if searchType is not None and (not isinstance(searchType, str) or searchType not in allowed_search_type):
        return _err("VALIDATION_ERROR", "Invalid 'searchType'.")
    if userId is not None and (not isinstance(userId, str) or len(userId.strip()) == 0):
        return _err("VALIDATION_ERROR", "Invalid 'userId'.")
    if storiesType is not None and (not isinstance(storiesType, str) or storiesType not in allowed_stories_type):
        return _err("VALIDATION_ERROR", "Invalid 'storiesType'.")
    if page is not None:
        if not isinstance(page, (int, float)) or int(page) != page or page < 0:
            return _err("VALIDATION_ERROR", "Invalid 'page'. Must be an integer >= 0.")
        page = int(page)
    if hitsPerPage is not None:
        if not isinstance(hitsPerPage, (int, float)) or int(hitsPerPage) != hitsPerPage or hitsPerPage < 1 or hitsPerPage > 100:
            return _err("VALIDATION_ERROR", "Invalid 'hitsPerPage'. Must be an integer between 1 and 100.")
        hitsPerPage = int(hitsPerPage)
    if limit is None:
        limit_n = 50
    else:
        if not isinstance(limit, (int, float)) or int(limit) != limit:
            return _err("VALIDATION_ERROR", "Invalid 'limit'. Must be an integer.")
        limit_n = int(limit)
        if limit_n < 1 or limit_n > 500:
            return _err("VALIDATION_ERROR", "Invalid 'limit'. Must be between 1 and 500.")
    offset = _parse_cursor(cursor)
    if cursor is not None and offset is None:
        return _err("VALIDATION_ERROR", "Invalid 'cursor'.")

    # Authenticate (ambient)
    try:
        os.makedirs(_DB, exist_ok=True)
    except Exception:
        return _err("UNAUTHORIZED", "Integration is not permitted for the caller.")

    # Log this tool call itself
    call_request_id = _gen_id("hnreq")
    created_at = _now_iso()
    _log_request({
        "id": call_request_id,
        "tool_name": "listRequests",
        "status": "received",
        "query": None,
        "search_type": None,
        "page": None,
        "hits_per_page": None,
        "story_hn_item_id": None,
        "comment_hn_item_id": None,
        "stories_type": None,
        "limit": None,
        "user_hn_username": None,
        "response_cached_object_ids": None,
        "upstream_provider": None,
        "upstream_latency_ms": None,
        "error_message": None,
        "created_at": created_at,
        "updated_at": created_at,
    })

    rows = _load("hn_requests.json")

    # Filter
    def _match(r):
        if toolName is not None and r.get("tool_name") != toolName:
            return False
        if status is not None and r.get("status") != status:
            return False
        if query is not None and r.get("query") != query:
            return False
        if searchType is not None and r.get("search_type") != searchType:
            return False
        if userId is not None and r.get("user_hn_username") != userId.strip():
            return False
        if storiesType is not None and r.get("stories_type") != storiesType:
            return False
        if page is not None and r.get("page") != page:
            return False
        if hitsPerPage is not None and r.get("hits_per_page") != hitsPerPage:
            return False
        return True

    filtered = [r for r in rows if _match(r)]

    # Sort reverse chronological by created_at then id
    def _key(r):
        return (r.get("created_at") or "", r.get("id") or "")
    filtered.sort(key=_key, reverse=True)

    if offset is None:
        offset = 0
    page_rows = filtered[offset: offset + limit_n]
    next_offset = offset + len(page_rows)
    has_more = next_offset < len(filtered)
    next_cursor = _make_cursor(next_offset) if has_more else None

    # Update call request status
    reqs2 = _load("hn_requests.json")
    for r in reqs2:
        if r.get("id") == call_request_id:
            r["status"] = "served_from_cache"
            r["response_cached_object_ids"] = [x.get("id") for x in page_rows if x.get("id")]
            r["updated_at"] = _now_iso()
            break
    _save("hn_requests.json", reqs2)

    return {
        "requestId": call_request_id,
        "data": page_rows,
        "meta": {
            "total": len(filtered),
            "limit": limit_n,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
        },
    }

