        if isinstance(upstreamLatencyMs, bool):
            return _err("VALIDATION_ERROR", "Parameter 'upstreamLatencyMs' must be a number.", upstreamLatencyMs=upstreamLatencyMs)
        if not isinstance(upstreamLatencyMs, (int, float)) or not (upstreamLatencyMs == upstreamLatencyMs) or abs(upstreamLatencyMs) == float("inf"):
            return _err("VALIDATION_ERROR", "Parameter 'upstreamLatencyMs' must be a finite number.", upstreamLatencyMs=upstreamLatencyMs)
        if upstreamLatencyMs < 0:
            return _err("VALIDATION_ERROR", "Parameter 'upstreamLatencyMs' must be >= 0.", upstreamLatencyMs=upstreamLatencyMs)

    if errorMessage is not None and not isinstance(errorMessage, str):
        return _err("VALIDATION_ERROR", "Parameter 'errorMessage' must be a string.", errorMessage=errorMessage)

    if status == "failed" and (errorMessage is None or not errorMessage.strip()):
        return _err("VALIDATION_ERROR", "Business rule: errorMessage is required when status='failed'.", status=status)

    t0 = time.time()
    reqs = _load("hn_requests.json")
    if not isinstance(reqs, list):
        reqs = []

    limit_err = _enforce_limits(reqs)
    if limit_err:
        return limit_err

    row = None
    for r in reqs:
        if r.get("id") == rid:
            row = r
            break
    if row is None:
        return _err("NOT_FOUND", "Request does not exist.", id=rid)

    transitions = {
        "received": {"served_from_cache", "fetched_upstream", "failed"},
        "served_from_cache": set(),
        "fetched_upstream": set(),
        "failed": set(),
    }
    cur = row.get("status")
    if cur not in transitions:
        return _err("INVALID_TRANSITION", "Request has an unknown current status; cannot transition safely.", id=rid, current_status=cur, new_status=status)
    if status != cur and status not in transitions[cur]:
        return _err("INVALID_TRANSITION", "Invalid request status transition.", id=rid, current_status=cur, new_status=status, allowed=list(transitions[cur]))

    # mutate only allowed fields
    row["status"] = status
    if upstreamProvider is not None:
        row["upstream_provider"] = upstreamProvider
    if upstreamLatencyMs is not None:
        row["upstream_latency_ms"] = int(round(float(upstreamLatencyMs)))
    if status == "failed":
        row["error_message"] = errorMessage
    elif errorMessage is not None:
        # allow clearing/overwriting error message only if failed? business rule says mutable but meaning stays; keep simple:
        row["error_message"] = errorMessage

    row["updated_at"] = _now_iso()
    _save("hn_requests.json", reqs)

    latency_ms = int(max(0, (time.time() - t0) * 1000))
    return {"request": row, "meta": {"updated": True, "latency_ms": latency_ms}}

def listCachedItems(itemType=None, status=None, hnItemId=None, rootStoryHnItemId=None, author=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0103000" if __import__("os").path.isdir("./environment_mix/0103000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # ---- Auth (ambient; permitted if datastore present) ----
    # No explicit credential parameters; only refuse if the service datastore is not available at all.
    # (If the vendor had a permission model collection, we'd enforce it here.)
    if not os.path.isdir(_DB):
        return _err("UNAUTHORIZED", "Integration not permitted for caller (datastore unavailable).")

    # ---- Validation ----
    allowed_item_types = {"story", "comment", "job", "poll", "pollopt"}
    allowed_status = {"active", "deleted", "dead", "tombstoned"}

    if itemType is not None:
        if not isinstance(itemType, str) or itemType not in allowed_item_types:
            return _err("VALIDATION_ERROR", "Invalid itemType.", allowed=sorted(list(allowed_item_types)))
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            return _err("VALIDATION_ERROR", "Invalid status.", allowed=sorted(list(allowed_status)))

    def _num_to_int(x, name):
        if x is None:
            return None
        if isinstance(x, bool):
            return _err("VALIDATION_ERROR", f"Invalid {name}.")
        if isinstance(x, int):
            return x
        if isinstance(x, float) and x.is_integer():
            return int(x)
        return _err("VALIDATION_ERROR", f"Invalid {name}.")

    hnItemId_i = _num_to_int(hnItemId, "hnItemId")
    if isinstance(hnItemId_i, dict) and hnItemId_i.get("error"):
        return hnItemId_i
    if hnItemId_i is not None and hnItemId_i <= 0:
        return _err("VALIDATION_ERROR", "hnItemId must be > 0.")

    rootStoryHnItemId_i = _num_to_int(rootStoryHnItemId, "rootStoryHnItemId")
    if isinstance(rootStoryHnItemId_i, dict) and rootStoryHnItemId_i.get("error"):
        return rootStoryHnItemId_i
    if rootStoryHnItemId_i is not None and rootStoryHnItemId_i <= 0:
        return _err("VALIDATION_ERROR", "rootStoryHnItemId must be > 0.")

    if author is not None and (not isinstance(author, str) or len(author) == 0):
        return _err("VALIDATION_ERROR", "author must be a non-empty string when provided.")

    if limit is None:
        limit_i = 50
    else:
        limit_i = _num_to_int(limit, "limit")
        if isinstance(limit_i, dict) and limit_i.get("error"):
            return limit_i
        if limit_i is None:
            limit_i = 50
        if limit_i < 1 or limit_i > 500:
            return _err("VALIDATION_ERROR", "limit must be between 1 and 500.")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string when provided.")

    # ---- Cursor handling ----
    # Cursor encodes the last seen (updated_at, id) pair so pagination is stable.
    def _decode_cursor(c):
        try:
            raw = base64.urlsafe_b64decode(c.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict):
                return None
            ua = obj.get("updated_at")
            rid = obj.get("id")
            if not isinstance(ua, str) or not isinstance(rid, str):
                return None
            return (ua, rid)
        except Exception:
            return None

    start_after = None
    if cursor:
        start_after = _decode_cursor(cursor)
        if start_after is None:
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    def _encode_cursor(updated_at, rid):
        payload = json.dumps({"updated_at": updated_at, "id": rid}, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(payload).decode("utf-8").rstrip("=")

    # ---- Read and filter ----
    items = _load("hn_items.json")
    if not isinstance(items, list):
        items = []

    filtered = []
    for it in items:
        if not isinstance(it, dict):
            continue
        if itemType is not None and it.get("item_type") != itemType:
            continue
        if status is not None and it.get("status") != status:
            continue
        if hnItemId_i is not None and it.get("hn_item_id") != hnItemId_i:
            continue
        if rootStoryHnItemId_i is not None and it.get("root_story_hn_item_id") != rootStoryHnItemId_i:
            continue
        if author is not None and it.get("hn_author") != author:
            continue
        filtered.append(it)

    # Sort newest first: updated_at desc, then id desc
    def _key(it):
        ua = it.get("updated_at") or ""
        rid = it.get("id") or ""
        return (ua, rid)

    filtered.sort(key=_key, reverse=True)

    # Apply cursor (start after the cursor item in the sorted order)
    if start_after is not None:
        ua0, id0 = start_after
        def _is_after(it):
            ua, rid = (it.get("updated_at") or "", it.get("id") or "")
            # since we are sorted desc, "after" means strictly less than cursor tuple
            return (ua, rid) < (ua0, id0)
        filtered = [it for it in filtered if _is_after(it)]

    total = len(filtered)
    page_items = filtered[:limit_i]
    has_more = total > len(page_items)
    next_cursor = None
    if has_more and page_items:
        last = page_items[-1]
        next_cursor = _encode_cursor(last.get("updated_at") or "", last.get("id") or "")

    # ---- Observability: log request to hn_requests ----
    reqs = _load("hn_requests.json")
    if not isinstance(reqs, list):
        reqs = []

    req_id = "hnreq_" + hashlib.sha256(f"{now}|listCachedItems|{time.time_ns()}".encode("utf-8")).hexdigest()[:24]
    latency_ms = int((time.time() - t0) * 1000)
    response_ids = [it.get("id") for it in page_items if isinstance(it, dict) and isinstance(it.get("id"), str)]

    req_row = {
        "id": req_id,
        "tool_name": "search",  # closest available in schema enum for list-style reads
        "status": "served_from_cache",
        "query": None,
        "search_type": None,
        "page": None,
        "hits_per_page": None,
        "story_hn_item_id": None,
        "comment_hn_item_id": None,
        "stories_type": None,
        "limit": limit_i,
        "user_hn_username": None,
        "response_cached_object_ids": response_ids,
        "upstream_provider": None,
        "upstream_latency_ms": None,
        "error_message": None,
        "created_at": now,
        "updated_at": now
    }
    reqs.append(req_row)
    _save("hn_requests.json", reqs)

    return {
        "items": page_items,
        "meta": {
            "total": total,
            "limit": limit_i,
            "has_more": has_more,
            "next_cursor": next_cursor
        }
    }

def tombstoneItem(id, reason=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0103000" if __import__("os").path.isdir("./environment_mix/0103000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0)
    def _now_iso():
        return _now().isoformat() + "Z"

    def _parse_num_as_int(v):
        if isinstance(v, bool) or v is None:
            return None
        if isinstance(v, int):
            return v
        if isinstance(v, float):
            if not (v == v and abs(v) != float("inf")):
                return None
            if int(v) != v:
                return None
            return int(v)
        return None

    hn_id = _parse_num_as_int(id)
    if hn_id is None or hn_id <= 0:
        return _err("VALIDATION_ERROR", "Parameter 'id' is required and must be a positive integer-valued number (hn_item_id).", id=id)
    if reason is not None and not isinstance(reason, str):
        return _err("VALIDATION_ERROR", "Parameter 'reason' must be a string when provided.", reason=reason)

    t0 = time.time()
    reqs = _load("hn_requests.json")
    if not isinstance(reqs, list):
        reqs = []

    # rate limits enforced via hn_requests
    def _parse_iso(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            ss = s[:-1] if s.endswith("Z") else s
            return datetime.datetime.fromisoformat(ss)
        except Exception:
            return None

    def _enforce_limits(reqs_):
        now_dt = _now()
        minute_ago = now_dt - datetime.timedelta(seconds=60)
        day_ago = now_dt - datetime.timedelta(days=1)
        per_min = 0
        per_day = 0
        for r in reqs_:
            ts = _parse_iso(r.get("created_at"))
            if not ts:
                continue
            if ts >= minute_ago:
                per_min += 1
            if ts >= day_ago:
                per_day += 1
        if per_min >= 240:
            return _err("RATE_LIMIT", "Rate limit exceeded (max 240 requests/min across this datastore).", limit_per_minute=240)
        if per_day >= 5000:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded (max 5000 requests/day across this datastore).", limit_per_day=5000)
        return None

    limit_err = _enforce_limits(reqs)
    if limit_err:
        return limit_err

    items = _load("hn_items.json")
    if not isinstance(items, list):
        items = []

    # Find item by hn_item_id
    idx = None
    for i, it in enumerate(items):
        if it.get("hn_item_id") == hn_id:
            idx = i
            break
    if idx is None:
        return _err("NOT_FOUND", "Item does not exist.", hn_item_id=hn_id)

    it = items[idx]
    cur = it.get("status")
    transitions = {
        "active": {"deleted", "dead", "tombstoned"},
        "dead": {"tombstoned"},
        "deleted": {"tombstoned"},
        "tombstoned": set(),
    }
    if cur not in transitions:
        return _err("INVALID_TRANSITION", "Item has unknown current status; cannot tombstone safely.", hn_item_id=hn_id, current_status=cur)
    if "tombstoned" not in transitions[cur]:
        return _err("INVALID_TRANSITION", "Invalid item status transition to tombstoned.", hn_item_id=hn_id, current_status=cur, new_status="tombstoned", allowed=list(transitions[cur]))

    # mutate
    it["status"] = "tombstoned"
    it["updated_at"] = _now_iso()
    items[idx] = it
    _save("hn_items.json", items)

    latency_ms = int(max(0, (time.time() - t0) * 1000))
    meta = {"hn_item_id": hn_id, "previous_status": cur, "new_status": "tombstoned", "latency_ms": latency_ms}
    if isinstance(reason, str) and reason.strip():
        meta["reason"] = reason.strip()
    return {"item": it, "meta": meta}
